class AddEditEngineeringQualityAssuranceComponent {
  get controls() {
    return this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm.controls;
  }
  get licenseProjectEngineeringMonthlyConsultantStaffRatesFormArr() {
    return this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm.get('licenseProjectEngineeringMonthlyConsultantStaffRates');
  }
  constructor(_licenseProjectEngineeringSupervisionPlannedReportDetailService, _qualityAndBusinessProgressService, _formBuilder, _sharedLicenseProjectService, _toastrNotificationService, _popupService) {
    this._licenseProjectEngineeringSupervisionPlannedReportDetailService = _licenseProjectEngineeringSupervisionPlannedReportDetailService;
    this._qualityAndBusinessProgressService = _qualityAndBusinessProgressService;
    this._formBuilder = _formBuilder;
    this._sharedLicenseProjectService = _sharedLicenseProjectService;
    this._toastrNotificationService = _toastrNotificationService;
    this._popupService = _popupService;
    this.subscriptions = [];
    this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList = [];
    this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm = this._formBuilder.group({
      currenrYear: [0],
      licenseProjectEngineeringMonthlyConsultantStaffRates: this._formBuilder.array([])
    });
    this.licenseProjectId = '00000000-0000-0000-0000-000000000000';
    this.showValidation = false;
  }
  ngOnInit() {
    this.getLicenseProjectIdStorage();
    this.observePopupEvents();
  }
  getLicenseProjectIdStorage() {
    this.licenseProjectId = this._sharedLicenseProjectService.getLicenseProjectIdStorage();
    if (this.licenseProjectId) {
      this.GetLicenseProjectEngineeringDetails();
    }
  }
  GetLicenseProjectEngineeringDetails() {
    this.subscriptions.push(this._licenseProjectEngineeringSupervisionPlannedReportDetailService.GetLicenseProjectEngineeringDetails(this.licenseProjectId).subscribe(res => {
      if (res) {
        this.years = this.getYearsBetween(new Date(res.startOn), new Date(res.endOn));
        if (this.years && this.years.length != 0 && !this.currenrYear) this.currenrYear = this.years[0];
        this.GetLicenseProjectEngineeringMonthlyConsultantStaffRates();
      }
    }));
  }
  GetLicenseProjectEngineeringMonthlyConsultantStaffRates() {
    this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm.controls.currenrYear.setValue(this.currenrYear);
    this.subscriptions.push(this._qualityAndBusinessProgressService.GetLicenseProjectEngineeringMonthlyConsultantStaffRates(this.licenseProjectId, this.currenrYear).subscribe(res => {
      if (res && res.length > 0) {
        this.addValuesToArrayForm(res);
      }
    }));
  }
  save() {
    this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList = this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm.controls.licenseProjectEngineeringMonthlyConsultantStaffRates.value;
    if (this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList && this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList.length > 0) {
      this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList.forEach(item => {
        item.licenseProjectId = this.licenseProjectId;
      });
      this.subscriptions.push(this._qualityAndBusinessProgressService.SaveLicenseProjectEngineeringMonthlyConsultantStaffRates(this.licenseProjectEngineeringMonthlyConsultantStaffRatesCreateUpdateList).subscribe(res => {
        if (res || res == 0) {
          this._toastrNotificationService.showSuccess('تم حفظ بيانات السنة');
          this.GetLicenseProjectEngineeringMonthlyConsultantStaffRates();
        }
      }));
    }
  }
  onChangeYear(data) {
    this.currenrYear = Number(data.target.value);
    this.save();
  }
  getYearsBetween(startDate, endDate) {
    const startYear = startDate.getFullYear();
    const endYear = endDate.getFullYear();
    const years = [];
    for (let year = startYear; year <= endYear; year++) {
      years.push(year);
    }
    years.sort((a, b) => a - b); // Sort in ascending order
    return years;
  }
  addValuesToArrayForm(licenseProjectEngineeringMonthlyConsultantStaffRatesList) {
    this.licenseProjectEngineeringMonthlyConsultantStaffRatesForm.controls.licenseProjectEngineeringMonthlyConsultantStaffRates.clear();
    // set Values into FormArr
    licenseProjectEngineeringMonthlyConsultantStaffRatesList.forEach(item => {
      let currentobj = this._formBuilder.group({
        id: item.id,
        licenseProjectUnitId: this.licenseProjectId,
        monthDate: item.monthDate,
        monthName: item.monthName,
        monthlyConsultantEngineerStaffAccordingPlan: item.monthlyConsultantEngineerStaffAccordingPlan,
        monthlyConsultantInspectorStaffAccordingPlan: item.monthlyConsultantInspectorStaffAccordingPlan
      });
      this.licenseProjectEngineeringMonthlyConsultantStaffRatesFormArr.push(currentobj);
    });
  }
  // popup
  observePopupEvents() {
    this.observeconfirmAction();
  }
  observeconfirmAction() {
    this.subscriptions.push(this._popupService.confirmAction.subscribe(res => {
      console.log(res);
      this.save();
    }));
  }
  ngOnDestroy() {
    this.subscriptions.forEach(sub => sub.unsubscribe());
  }
}
