  validateDeedInfo() {
    this.projectLandDeedForm.controls.id.setValue('00000000-0000-0000-0000-000000000000');
    this.projectLandDeedForm.controls.typeId.setValue(Number(this.projectLandDeedForm.controls.typeId.value));
    if (!this.projectLandDeedForm.valid) {
      this.showValidation = true;
      this._toastrNotificationService.showError(this.localization.PleaseAddAllRequiredFields);
      return;
    }
    if (!this.projectLandDeedCreateUpdate.id) this.projectLandDeedCreateUpdate.id = '00000000-0000-0000-0000-000000000000';
    if (!this.projectLandDeedCreateUpdate.approvedOn) this.projectLandDeedCreateUpdate.approvedOn = null;
    console.log('validateDeedInfo this.projectLandDeedCreateUpdate', this.projectLandDeedCreateUpdate);
    this.subscriptions.push(this._projectLandDeedService.ValidateDeedInfo(this.projectLandDeedCreateUpdate).subscribe(res => {
      if (res.isDone) {
        this.deedFromIntegration = res.data;
        this._projectLandDeedService.SetDeedIntegrationResponseDto(res.data);
        this.hasOwnerData = true;
        this.initRows(this.deedFromIntegration.deedOwners);
        // this._toastrService.success(this.localization.savedSuccessfully)
        // console.log(this.deedFromIntegration)
      }
      // else
      //   this._toastrService.error(res.message);
    }));
  }

  save() {
    this.changeOwnerFileValidation(null);
    if (!this.projectLandDeed.id) this.projectLandDeed.id = '00000000-0000-0000-0000-000000000000';
    this.controls.id.setValue(this.projectLandDeed.id);
    if (!this.projectLandDeedForm.valid) {
      this._toastrNotificationService.showError(this.localization.PleaseAddAllRequiredFields);
      this.showValidation = true;
      return;
    }
    if (!this.deedOwnerForm.valid) {
      this.showValidation = true;
      this._toastrNotificationService.showError(this.localization.PleaseAddAllRequiredFields);
      this.projectLandDeedForm?.markAllAsTouched();
      return;
    }
    // if (!this.projectLandDeed.approvedOn) this.projectLandDeed.approvedOn = this.projectLandDeed.issueOn;
    if (!this.projectLandDeed.approvedOn) this.projectLandDeed.approvedOn = null;
    // this.subscriptions.push(
    //   this._projectLandDeedService.getDeedIntegrationResponseDto().subscribe((deed) => {
    //     this.projectLandDeed.data = deed
    //   }))
    this.projectLandDeed.data = this.deedFromIntegration;
    if (this.projectLandDeed.typeId) {
      this.projectLandDeed.typeId = +this.projectLandDeed.typeId;
    }
    let model = {
      deedDate: this.projectLandDeed.data.deedDate,
      id: this.projectLandDeed.id,
      integrationType: this.projectLandDeed.integrationType,
      issueOn: this.projectLandDeed.issueOn,
      number: this.projectLandDeed.data.deedNo?.toString(),
      licenseProjectsId: this.projectLandDeed.licenseProjectsId,
      typeId: this.projectLandDeed.typeId,
      deedOwners: this.projectLandDeed.data.deedOwners
    };
    this.subscriptions.push(this._projectLandDeedService.SaveDeedData(model).subscribe(res => {
      if (res.isDone) {
        this._toastrService.success(this.localization.savedSuccessfully);
        this._projectLandDeedService.SetSubjectListObjs(res.data);
        this._projectLandDeedService.getSubjectListObjs().subscribe(subjectObj => {
          this.projectLandDeedList = subjectObj;
          this.projectLandDeedList.forEach(x => {
            x.typeName = this.deedTypes.find(t => t.id == x.typeId)?.name;
          });
        });
        this._popupService.dismissDialog();
      }
      // else
      //   this.__toastrNotificatioService.showError(res.message);
    }));
  }
